#include <iostream>
#include <stack>
#include <string>
using namespace std;

bool matching(char open, char close) {
    return (open == '(' && close == ')') || (open == '[' && close == ']') || (open == '{' && close == '}');
}

int main() {
    string s;
    cin >> s;
    stack<char> open;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') open.push(c);
        else {
            if (open.empty() || !matching(open.top(), c)) {
                cout << "NO\n";
                return 0;
            }
            open.pop();
        }
    }
    cout << (open.empty() ? "YES" : "NO") << '\n';
    return 0;
}

#include <iostream>
#include <queue>
using namespace std;

int main() {
    queue<int> pending;
    pending.push(1);
    pending.push(2);
    while (!pending.empty()) {
        cout << pending.front() << ' ';
        pending.pop();
    }
    return 0;
